class Solution {
  public boolean canMakeSubsequence(String s, String t) {
    int n = s.length(), m = t.length();
    int[] pre = new int[n + 1], suf = new int[n + 2];
    pre[0] = 0;
    int p = 0;
    for (int i = 0; i < n; i++) {
      while (p < m && t.charAt(p) != s.charAt(i)) p++;
      if (p >= m) {
        for (int j = i + 1; j <= n; j++) pre[j] = m + 1;
        break;
      }
      p++;
      pre[i + 1] = p;
    }
    if (pre[n] <= m) return true;
    int q = m;
    suf[n] = m;
    boolean broken = false;
    for (int i = n - 1; i >= 0; i--) {
      if (broken) {
        suf[i] = -1;
        continue;
      }
      q--;
      while (q >= 0 && t.charAt(q) != s.charAt(i)) q--;
      if (q < 0) {
        broken = true;
        suf[i] = -1;
      } else suf[i] = q;
    }
    for (int i = 0; i < n; i++) {
      if (pre[i] > m || suf[i + 1] < 0) continue;
      if (pre[i] < suf[i + 1]) return true;
    }
    return false;
  }
}
